SELECT t1.PSN_NAME AS `基金经理`, t2.REPORT_DATE AS `报告期`, ROUND(SUM(t2.NET_VALUE) / 100000000, 2) AS `在管总规模(亿元)` FROM FUND_AND_MANAGER_MAPPING t1 INNER JOIN FUND_ASSET_ALLOCATION t2 ON t1.FUND_HCODE = t2.FUND_HCODE WHERE t1.PSN_NAME = '谢治宇' AND t1.PSN_HCODE IN (SELECT PSN_HCODE FROM FUND_MANAGER_INFO WHERE INST_NAME LIKE '%兴证全球%' OR INST_FULL_NAME LIKE '%兴证全球%') AND t1.BEGIN_DATE <= (SELECT MAX(REPORT_DATE) FROM FUND_ASSET_ALLOCATION) AND (t1.END_DATE IS NULL OR t1.END_DATE >= (SELECT MAX(REPORT_DATE) FROM FUND_ASSET_ALLOCATION)) AND t1.HISVALID = 1 AND t2.REPORT_DATE = (SELECT MAX(REPORT_DATE) FROM FUND_ASSET_ALLOCATION) AND t2.HISVALID = 1 AND t2.NET_VALUE IS NOT NULL GROUP BY t1.PSN_NAME, t2.REPORT_DATE;
